# test_find_missing.py
import pytest

from missing import find_missing


@pytest.mark.parametrize(
    ("nums", "expected"),
    [
        ([3, 0, 1], 2),                          # normal unordered case
        ([0, 2], 1),                             # middle value missing
        ([9, 6, 4, 2, 3, 5, 7, 0, 1], 8),        # larger unordered case
        ([1, 2, 3, 4, 5], 0),                    # first value missing
        ([0, 1, 2, 3, 4], 5),                    # last value missing
    ],
)
def test_find_missing_happy_paths(nums, expected):
    assert find_missing(nums) == expected


@pytest.mark.parametrize(
    ("nums", "expected"),
    [
        ([], 0),      # n = 0, missing 0
        ([0], 1),     # sequence [0, 1], missing 1
        ([1], 0),     # sequence [0, 1], missing 0
    ],
)
def test_find_missing_edge_cases(nums, expected):
    assert find_missing(nums) == expected


def test_find_missing_all_missing_values_for_small_sequences():
    for n in range(25):
        for missing in range(n + 1):
            nums = [x for x in range(n + 1) if x != missing]
            nums.reverse()  # ensure order does not matter

            assert find_missing(nums) == missing


def test_find_missing_large_sequence():
    n = 10_000
    missing = 7_777
    nums = [x for x in range(n + 1) if x != missing]

    assert find_missing(nums) == missing


def test_find_missing_does_not_mutate_input():
    nums = [3, 0, 1]
    original = nums.copy()

    find_missing(nums)

    assert nums == original


@pytest.mark.parametrize("bad_input", [None, 123, object()])
def test_find_missing_invalid_input_type_raises_type_error(bad_input):
    with pytest.raises(TypeError):
        find_missing(bad_input)


@pytest.mark.parametrize(
    "nums",
    [
        [0, "1"],
        [0, None],
        [0, object()],
    ],
)
def test_find_missing_non_numeric_elements_raise_type_error(nums):
    with pytest.raises(TypeError):
        find_missing(nums)
